        // which C does not change during the call.
        let bytes = unsafe { bytes(str, str_len) };
        let (code_point, len) = barrier(
            || match decode_char(bytes) {
                Ok((c, len)) => (u32::from(c), c_int::try_from(len).unwrap_or(-1)),
