/// A table built at compile time, as `ubc_check.c`'s port builds `sha1_dvs`: two vectors and
/// the terminator.
static TABLE: [DvInfo; 3] = [
    record(1, 58, 0, 0x0800_0000),
    record(2, 65, 31, 0xB400_0008),
    record(0, 0, 0, 0),
];

#[test]
fn new_keeps_every_field_of_the_c_tables_first_record() {
    let r = i_43_0();
    let h = r.as_ref();
    assert_eq!(h.dv_type(), 1);
    assert_eq!(h.recompression_step(), 58);
    assert_eq!(h.mask_bit(), 0);
    assert_eq!(h.message_difference(), &DM_I_43_0);
    let debug = format!("{r:?}");
    assert!(debug.starts_with(
        "DvInfo { dv_type: 1, k: 43, b: 0, recompression_step: 58, mask_word: 0, mask_bit: 0, \
         message_difference: [134217728, 2550136844,"
    ));
}

#[test]
fn new_builds_the_terminator() {
    let r = terminator();
    let h = r.as_ref();
    assert_eq!(h.dv_type(), 0);
    assert_eq!(h.recompression_step(), 0);
    assert_eq!(h.mask_bit(), 0);
    assert_eq!(h.message_difference(), &[0; 80]);
}

/// The step indexes `sha1.c`'s 80 saved states, and the bit shifts a 32-bit mask: each bound is
/// kept on both sides, and `DVMASKSIZE`'s one word is the only one.
#[test]
fn new_refuses_a_step_bit_or_word_sha1_c_cannot_read() {
    for step in [0, 1, 58, 65, 79] {
        let r = with(step, 0, 0).expect("in range");
        assert_eq!(
            r.as_ref().recompression_step(),
            usize::try_from(step).unwrap()
        );
    }
    for step in [-1, 80, 81, i32::MIN, i32::MAX] {
        assert_eq!(with(step, 0, 0), None, "step {step}");
    }
    for bit in [0, 1, 16, 31] {
        let r = with(58, 0, bit).expect("in range");
        assert_eq!(r.as_ref().mask_bit(), u32::try_from(bit).unwrap());
    }
    for bit in [-1, 32, 33, i32::MIN, i32::MAX] {
        assert_eq!(with(58, 0, bit), None, "bit {bit}");
    }
    for word in [-1, 1, 2, i32::MIN, i32::MAX] {
        assert_eq!(with(58, word, 0), None, "word {word}");
    }
}

/// The type and the parameters `k` and `b` take any value: `sha1.c` only compares the type
/// with `0`, and reads neither parameter.
#[test]
fn new_takes_any_type_and_parameters() {
    for v in [i32::MIN, -1, 0, 1, 2, 3, i32::MAX] {
        let r = DvInfo::new(v, v, v, 65, 0, 31, [u32::MAX; 80]).expect("in range");
        assert_eq!(r.as_ref().dv_type(), v);
        assert!(format!("{r:?}").contains(&format!("k: {v}, b: {v},")));
        assert_eq!(r.as_ref().message_difference(), &[u32::MAX; 80]);
    }
}

/// Read as `sha1_process` reads `sha1_dvs`: up to the record whose type is `0`, each selected
/// by its bit of the mask.
#[test]
fn a_static_table_is_read_up_to_its_terminator() {
    let mask: u32 = 0x8000_0000;
    let mut selected = Vec::new();
    let mut i = 0;
    while TABLE[i].as_ref().dv_type() != 0 {
        let r = TABLE[i].as_ref();
        if mask & (1 << r.mask_bit()) != 0 {
            selected.push((r.recompression_step(), r.message_difference()[0]));
        }
        i += 1;
    }
    assert_eq!(i, 2);
    assert_eq!(selected, [(65, 0xB400_0008)]);
}

#[test]
fn copies_and_equality_cover_every_field() {
    let r = i_43_0();
    let copy = r;
    assert_eq!(copy, r);
    assert_eq!(r.as_ref().copied(), r);
    assert_eq!(r.as_ref(), copy.as_ref());
    // Fields no getter reads still count.
    let other_k = DvInfo::new(1, 44, 0, 58, 0, 0, DM_I_43_0).unwrap();
    let other_b = DvInfo::new(1, 43, 2, 58, 0, 0, DM_I_43_0).unwrap();
    let mut dm = DM_I_43_0;
    dm[79] ^= 1;
    let other_dm = DvInfo::new(1, 43, 0, 58, 0, 0, dm).unwrap();
    for other in [other_k, other_b, other_dm, terminator()] {
        assert_ne!(other, r);
        assert_ne!(other.as_ref(), r.as_ref());
    }
}

#[test]
fn handles_read_the_same_record() {
    let mut r = i_43_0();
    let expected = format!("{r:?}");
    let shared: DvInfoRef<'_> = r.as_ref();
    let dm = shared.message_difference();
    assert_eq!(format!("{shared:?}"), expected);
    assert_eq!(dm[1], 0x9800_000C);
    let mut m = r.as_mut();
    assert_eq!(format!("{m:?}"), expected);
    let reborrowed = m.as_mut();
    assert_eq!(reborrowed.as_ref().recompression_step(), 58);
    assert_eq!(m.as_ref().copied(), i_43_0());
}
//! `src/util/hash/sha1dc/ubc_check.c`: [`DvInfo`], the record of one disturbance vector,
//! through its safe API alone.
//!
//! A record holds plain data, which Rust values are built, copied and read through without C:
//! its handles reborrow, and the message difference a shared handle lends is read beside the
//! other handles that share it (Miri, `BSan`); records, their shared handles and an exclusive
//! one cross threads, and a `static` table and a shared value are read from several at once
//! (`TSan`, for its `Send` and `Sync`). The lent difference outliving its record, and a shared
//! handle beside the exclusive one, are in `compile_fail/`. None reaches C, so Miri runs them
//! all.

use std::sync::Barrier;
use std::thread;

use libgit2_crustify::libgit2::src::util::hash::sha1dc::ubc_check::{DvInfo, DvInfoMut, DvInfoRef};

/// A record of the given type, step and bit, whose message difference counts up from `tag`.
const fn record(dv_type: i32, step: i32, bit: i32, tag: u32) -> DvInfo {
    let mut dm = [0; 80];
    let (mut j, mut word) = (0, tag);
    while j < 80 {
        dm[j] = word;
        j += 1;
        word += 1;
    }
    match DvInfo::new(dv_type, 43, 0, step, 0, bit, dm) {
        Some(r) => r,
        None => panic!("out of range"),
    }
}

/// A table as `ubc_check.c`'s port builds `sha1_dvs`: a `static`, which needs `Sync`.
static TABLE: [DvInfo; 3] = [
    record(1, 58, 3, 0x300),
    record(2, 65, 31, 0x1F00),
    record(0, 0, 0, 0),
];

/// Every field the getters reach, folded into one value.
fn read_all(r: DvInfoRef<'_>) -> u64 {
    let dm = r.message_difference();
    let sum: u64 = dm.iter().map(|&w| u64::from(w)).sum();
    sum + u64::from(r.mask_bit())
        + u64::try_from(r.recompression_step()).unwrap()
        + u64::try_from(r.dv_type()).unwrap()
}

fn read_through(m: &DvInfoMut<'_>) -> u64 {
    read_all(m.as_ref())
}

#[test]
fn handles_reborrow_and_lend_the_difference_beside_each_other() {
    let mut r = record(1, 58, 7, 0x700);
    let expected = read_all(r.as_ref());
    let mut m = r.as_mut();
    assert_eq!(read_through(&m.as_mut()), expected);
    let shared = m.as_ref();
    let again = shared;
    let dm = shared.message_difference();
    assert_eq!(read_all(again), expected);
    assert_eq!(dm[79], 0x700 + 79);
    assert_eq!(read_through(&m), expected);
    let first = r.as_ref().message_difference();
    let second = r.as_ref().message_difference();
    assert_eq!(first, second);
    // A copy outlives the record it was taken from.
    let copy = {
        let inner = record(1, 58, 7, 0x700);
        inner.as_ref().copied()
    };
    assert_eq!(read_all(copy.as_ref()), expected);
}

#[test]
fn records_cross_threads_and_shared_ones_are_read_concurrently() {
    let local = record(2, 65, 12, 0xC00);
    let expected_local = read_all(local.as_ref());
    let expected_table: Vec<u64> = TABLE.iter().map(|r| read_all(r.as_ref())).collect();
    let shared = local.as_ref();
    let barrier = Barrier::new(4);
    thread::scope(|s| {
        for _ in 0..2 {
            s.spawn(|| {
                barrier.wait();
                for _ in 0..50 {
                    assert_eq!(read_all(shared), expected_local);
                    for (r, &e) in TABLE.iter().zip(&expected_table) {
                        assert_eq!(read_all(r.as_ref()), e);
                    }
                }
            });
        }
        s.spawn(|| {
            barrier.wait();
            for _ in 0..50 {
                assert_eq!(read_all(local.as_ref()), expected_local);
                assert_eq!(TABLE[1].as_ref().message_difference()[0], 0x1F00);
            }
        });
        barrier.wait();
        assert_eq!(read_all(TABLE[0].as_ref()), expected_table[0]);
    });
    let mut moved = local;
    let handle = thread::spawn(move || {
        let r = moved;
        read_all(r.as_ref())
    });
    assert_eq!(handle.join().unwrap(), expected_local);
    let exclusive = moved.as_mut();
    let from_thread = thread::scope(|s| s.spawn(move || read_through(&exclusive)).join().unwrap());
    assert_eq!(from_thread, expected_local);
}
