//! Scratch (not committed): sha1.c's C detects the SHAttered collision through the exports.
#![expect(unsafe_code, missing_docs, reason = "scratch")]
unsafe extern "C" {
    fn SHA1DCInit(ctx: *mut u64);
    fn SHA1DCSetSafeHash(ctx: *mut u64, safehash: i32);
    fn SHA1DCUpdate(ctx: *mut u64, buf: *const u8, len: usize);
    fn SHA1DCFinal(out: *mut u8, ctx: *mut u64) -> i32;
}
fn digest(data: &[u8]) -> (i32, [u8; 20]) {
    let mut ctx = vec![0_u64; 2048];
    let mut out = [0_u8; 20];
    unsafe { SHA1DCInit(ctx.as_mut_ptr()) };
    unsafe { SHA1DCSetSafeHash(ctx.as_mut_ptr(), 0) };
    unsafe { SHA1DCUpdate(ctx.as_mut_ptr(), data.as_ptr(), data.len()) };
    let found = unsafe { SHA1DCFinal(out.as_mut_ptr(), ctx.as_mut_ptr()) };
    (found, out)
}
#[test]
fn shattered_is_detected_through_the_exports() {
    let pdf = std::fs::read(concat!(env!("CARGO_MANIFEST_DIR"), "/c/tests/resources/sha1/shattered-1.pdf")).unwrap();
    let (found, out) = digest(&pdf);
    assert_eq!(found, 1);
    assert_eq!(out[..4], [0x38, 0x76, 0x2c, 0xf7]);
    let (found, _) = digest(&pdf[..300]);
    assert_eq!(found, 0);
    let mut other = pdf.clone(); other[200] ^= 1;
    assert_eq!(digest(&other).0, 0);
}
